@import url("https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400..700;1,9..144,400..700&family=IBM+Plex+Mono:wght@400;500;600&display=block");

/* One X in-feed image: 1600 x 900 (16:9). Each poster is a single .poster element. */
:root {
  --paper: #f2ede2;
  --ink: #16150f;
  --muted: #6b6658;
  --rule: #cfc7b4;
  --accent: #c23620;
  --confirmed: #1e6b48;
  --serif: "Fraunces", Georgia, serif;
  --mono: "IBM Plex Mono", Consolas, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body { width: 1600px; height: 900px; overflow: hidden; background: var(--paper); }

.poster {
  width: 1600px;
  height: 900px;
  padding: 64px 88px 60px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--mono);
  position: relative;
  overflow: hidden;
}

.poster.dark {
  --paper: #14130e;
  --ink: #f2ede2;
  --muted: #a39c8a;
  --rule: #3a372d;
  --accent: #f0603f;
}

.top, .foot {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 22px;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.top { padding-bottom: 22px; border-bottom: 2px solid var(--ink); }
.foot { padding-top: 22px; border-top: 1px solid var(--rule); }

.mark {
  font-family: var(--serif);
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.mark i { color: var(--accent); font-style: normal; }

.foot b { color: var(--ink); font-weight: 500; }

h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-variation-settings: "opsz" 144;
  letter-spacing: -0.025em;
  line-height: 0.98;
}
h1 em { font-style: italic; color: var(--accent); }

.lede { font-size: 26px; line-height: 1.45; color: var(--ink); }
.label { font-size: 19px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }

/* ---------- 1. disagreement ---------- */
.split { display: grid; grid-template-columns: 1fr 600px; gap: 72px; align-items: center; }
.split h1 { font-size: 94px; }
.split .lede { margin-top: 34px; max-width: 700px; }

.snapshot {
  position: relative;
  background: #fbf8f1;
  border: 2px solid var(--ink);
  box-shadow: 12px 12px 0 var(--ink);
  padding: 30px 34px 34px;
}
.snapshot .label { padding-bottom: 18px; border-bottom: 1px solid var(--rule); }
.reading { padding: 20px 0; border-bottom: 1px solid var(--rule); }
.reading:last-of-type { border-bottom: 0; padding-bottom: 0; }
.reading .field { font-size: 19px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }
.pair { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 8px; }
.pair small { display: block; font-size: 17px; color: var(--muted); }
.pair strong { display: block; font-family: var(--serif); font-size: 46px; font-weight: 500; letter-spacing: -0.02em; line-height: 1.1; white-space: nowrap; }
.pair div:first-child strong { color: var(--accent); text-decoration: line-through; text-decoration-thickness: 3px; }
.stamp {
  position: absolute;
  top: -30px;
  right: -34px;
  transform: rotate(7deg);
  padding: 10px 18px;
  border: 4px solid var(--accent);
  background: var(--paper);
  color: var(--accent);
  font-size: 24px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

/* ---------- 2. ten in a hundred ---------- */
.stat { display: grid; grid-template-columns: 1fr 520px; gap: 80px; align-items: center; }
.figure { font-family: var(--serif); font-variation-settings: "opsz" 144; font-weight: 500; font-size: 290px; line-height: 0.82; letter-spacing: -0.05em; white-space: nowrap; }
.figure b { color: var(--accent); font-weight: 600; }
.figure span { font-size: 150px; font-style: italic; letter-spacing: -0.03em; color: var(--muted); }
.stat h1 { font-size: 50px; line-height: 1.1; margin-top: 30px; letter-spacing: -0.015em; }
.stat .lede { margin-top: 24px; color: var(--muted); max-width: 800px; }
.dots { display: grid; grid-template-columns: repeat(10, 1fr); gap: 16px; }
.dots i { aspect-ratio: 1; border-radius: 50%; border: 2px solid var(--rule); }
.dots i.on { background: var(--accent); border-color: var(--accent); }
.dots-key { margin-top: 26px; display: flex; gap: 34px; font-size: 19px; color: var(--muted); }
.dots-key span::before { content: ""; display: inline-block; width: 16px; height: 16px; border-radius: 50%; margin-right: 10px; border: 2px solid var(--rule); vertical-align: -2px; }
.dots-key span.on::before { background: var(--accent); border-color: var(--accent); }

/* ---------- 3. how it works ---------- */
.flow { display: grid; grid-template-rows: auto auto; align-content: center; gap: 50px; }
.flow h1 { font-size: 104px; }
.steps { display: grid; grid-template-columns: repeat(4, 1fr) 1.25fr; gap: 0; }
.step { padding: 22px 26px 0 0; border-top: 2px solid var(--ink); position: relative; }
.step::before { content: ""; position: absolute; top: -9px; left: 0; width: 16px; height: 16px; border-radius: 50%; background: var(--ink); }
.step .n { font-size: 19px; color: var(--muted); letter-spacing: 0.1em; }
.step h2 { font-family: var(--serif); font-size: 42px; font-weight: 500; letter-spacing: -0.02em; margin: 6px 0 8px; }
.step p { font-size: 21px; line-height: 1.4; color: var(--muted); }
.outcome { border-top: 0; padding: 0; display: grid; gap: 14px; margin-top: -2px; }
.outcome::before { display: none; }
.outcome div { border: 2px solid var(--ink); padding: 14px 20px 16px; }
.outcome h2 { font-size: 34px; margin: 0 0 2px; }
.outcome .yes { background: var(--confirmed); border-color: var(--confirmed); color: #f2ede2; }
.outcome .yes p { color: #d6e6dc; }
.outcome .no h2 { color: var(--accent); }

@import url("https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400..700;1,9..144,400..700&family=IBM+Plex+Mono:wght@400;500&display=block");

/*
  One X in-feed image: 1600 x 900 (16:9). Each poster is a single .poster element.

  Why these choices:
  - Fraunces: a newspaper-style serif, because the subject is house adverts and their prices.
  - IBM Plex Mono: only for the small source note, so it reads as a record, not a slogan.
  - One accent red, used once per poster on the words or number the eye should land on.
  - Paper background for the product posters; the dark one sets the single statistic apart.
*/
:root {
  --paper: #f2ede2;
  --ink: #16150f;
  --muted: #6b6658;
  --rule: #cfc7b4;
  --accent: #c23620;
  --serif: "Fraunces", Georgia, serif;
  --mono: "IBM Plex Mono", Consolas, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body { width: 1600px; height: 900px; overflow: hidden; background: var(--paper); }

.poster {
  width: 1600px;
  height: 900px;
  padding: 60px 88px 52px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--serif);
  overflow: hidden;
}

.poster.dark {
  --paper: #14130e;
  --ink: #f2ede2;
  --muted: #a39c8a;
  --rule: #3a372d;
  --accent: #f0603f;
}

.top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-bottom: 20px;
  border-bottom: 2px solid var(--ink);
}
.mark { font-size: 40px; font-weight: 600; letter-spacing: -0.01em; }
.mark i { color: var(--accent); font-style: normal; }
.top span:last-child, .foot { font-family: var(--mono); font-size: 22px; color: var(--muted); }
.foot { padding-top: 20px; border-top: 1px solid var(--rule); }

.body { display: grid; align-content: center; }

h1 {
  font-weight: 500;
  font-variation-settings: "opsz" 144;
  letter-spacing: -0.025em;
  line-height: 1;
}
h1 em { font-style: italic; color: var(--accent); }

.sub { font-size: 40px; line-height: 1.25; letter-spacing: -0.01em; color: var(--muted); }

/* what-it-does: type only */
.say h1 { font-size: 118px; }
.say .sub { margin-top: 40px; }

/* two-sizes: the two numbers are the picture */
.versus h1 { font-size: 80px; }
.versus .pair { display: grid; grid-template-columns: auto auto auto; justify-content: start; align-items: start; column-gap: 56px; margin: 30px 0 34px; }
.versus .num { font-size: 216px; font-weight: 500; font-variation-settings: "opsz" 144; letter-spacing: -0.04em; line-height: 0.95; white-space: nowrap; }
.versus .ne { font-size: 150px; line-height: 1.3; color: var(--accent); }
.versus small { display: block; margin-top: 10px; font-family: var(--mono); font-size: 26px; color: var(--muted); }

/* ninety-in-a-hundred: one number, one grid of dots */
.count { grid-template-columns: minmax(0, 1fr) 470px; column-gap: 80px; align-items: center; }
.count .num { font-size: 270px; font-weight: 500; font-variation-settings: "opsz" 144; letter-spacing: -0.05em; line-height: 0.82; white-space: nowrap; }
.count .num b { color: var(--accent); font-weight: 600; }
.count .num i { font-size: 130px; letter-spacing: -0.03em; color: var(--muted); }
.count h1 { font-size: 72px; margin-top: 30px; }
.count .sub { font-size: 36px; margin-top: 24px; }
.dots { display: grid; grid-template-columns: repeat(10, 1fr); gap: 14px; }
.dots i { aspect-ratio: 1; border-radius: 50%; border: 2px solid var(--muted); }
.dots i.missing { background: var(--accent); border-color: var(--accent); }
.key { margin-top: 24px; font-family: var(--mono); font-size: 22px; color: var(--muted); }
.key b { color: var(--accent); font-weight: 500; }
